candidates.final_sql:
SELECT CAST(COUNT(CDSCode) AS REAL) / 12 AS monthly_avg_schools_opened
FROM schools
WHERE strftime('%Y', OpenDate) = '1980' AND "District Type" = 'Elementary School District' AND "County" = 'Alameda County' AND "DOC" = '52';

